import heapq
class Solution:
    def convertArray(self, nums: List[int]) -> int:
        def cost(a):
            h, total = [], 0
            for x in a:
                heapq.heappush(h, -x)
                if -h[0] > x:
                    total += -h[0] - x
                    heapq.heapreplace(h, -x)
            return total
        return min(cost(nums), cost(nums[::-1]))

