class Solution {
public:
    int convertArray(vector<int>& nums) {
        auto cost = [](vector<int> a) {
            priority_queue<int> pq;
            long long total = 0;
            for (int x : a) {
                pq.push(x);
                if (pq.top() > x) { total += pq.top() - x; pq.pop(); pq.push(x); }
            }
            return total;
        };
        vector<int> rev(nums.rbegin(), nums.rend());
        return (int)min(cost(nums), cost(rev));
    }
};

