class Solution {
    private long cost(int[] a) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        long total = 0;
        for (int x : a) {
            pq.offer(x);
            if (pq.peek() > x) { total += pq.peek() - x; pq.poll(); pq.offer(x); }
        }
        return total;
    }
    public int convertArray(int[] nums) {
        int[] rev = nums.clone();
        for (int l = 0, r = rev.length - 1; l < r; l++, r--) { int t = rev[l]; rev[l] = rev[r]; rev[r] = t; }
        return (int)Math.min(cost(nums), cost(rev));
    }
}

