var convertArray = function(nums) {
    const cost = (a) => {
        const h = [];
        const push = (v) => { h.push(v); let i = h.length - 1;
            while (i > 0) { const p = (i - 1) >> 1; if (h[p] >= h[i]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
        const pop = () => { const t = h[0], l = h.pop(); if (h.length) { h[0] = l; let i = 0;
            for (;;) { let c = 2 * i + 1; if (c >= h.length) break;
                if (c + 1 < h.length && h[c + 1] < h[c]) c++;
                if (h[i] <= h[c]) break; [h[i], h[c]] = [h[c], h[i]]; i = c; } } return t; };
        let total = 0;
        for (const x of a) { push(-x); if (-h[0] > x) { total += -h[0] - x; pop(); push(-x); } }
        return total;
    };
    return Math.min(cost(nums), cost([...nums].reverse()));
};

