        INF = float('inf')
        def solve(a):
            M = max(a)
            dp = [abs(a[0] - v) for v in range(M + 1)]
            for x in a[1:]:
                ndp, best = [], INF
                for v in range(M + 1):
                    best = min(best, dp[v])
                    ndp.append(best + abs(x - v))
                dp = ndp
            return min(dp)
        return min(solve(nums), solve(nums[::-1]))

