class Solution {
    private long solve(int[] a) {
        int M = 0;
        for (int v : a) M = Math.max(M, v);
        long[] dp = new long[M + 1];
        for (int v = 0; v <= M; v++) dp[v] = Math.abs(a[0] - v);
        for (int i = 1; i < a.length; i++) {
            long[] ndp = new long[M + 1];
            long best = Long.MAX_VALUE;
            for (int v = 0; v <= M; v++) {
                best = Math.min(best, dp[v]);
                ndp[v] = best + Math.abs(a[i] - v);
            }
            dp = ndp;
        }
        long ans = Long.MAX_VALUE;
        for (long v : dp) ans = Math.min(ans, v);
        return ans;
    }
    public int convertArray(int[] nums) {
        int[] rev = nums.clone();
        for (int l = 0, r = rev.length - 1; l < r; l++, r--) { int t = rev[l]; rev[l] = rev[r]; rev[r] = t; }
        return (int)Math.min(solve(nums), solve(rev));
    }
}

